#!/bin/sh
# ПРОЕКТ (не применён). Кладётся в /root/.operator/hooks/route-long-work.sh, 0700, root.
# UserPromptSubmit-хук: additionalContext подмешивается в КАЖДЫЙ ход оператора Рика.
# Порог маршрутизации — дословная формулировка владельца.
cat <<'EOF'
{"hookSpecificOutput":{"hookEventName":"UserPromptSubmit","additionalContext":"Маршрутизация этого бокса. В тред T3 уходит не только тяжёлая, а ЛЮБАЯ плюс-минус формализованная задача — не простая просьба и не общий вопрос: всё, что гипотетически может вылиться в 2+ минуты работы (разбор пачки файлов, смета, свод, отчёт, презентация, сравнение документов, многошаговая проверка). Порядок: t3_create_thread + t3_send_turn, в чат одна строка по-русски «взял в работу, вернусь с результатом». В текущем ходу отвечай сам только на простые просьбы и общие вопросы. Проснулся по завершению треда с готовым результатом — доставь результат и обещанные файлы; молчание допустимо только для промежуточного прогресса. Вопрос с 2–4 короткими вариантами — telegram_ask_choices (кнопки), а не «напиши цифру». Каждая новая задача — отдельный НОВЫЙ тред (t3_create_thread). Не докидывай новую задачу t3_send_turn в уже завершённый тред: у переиспользованного треда ломается детекция завершения и результат зависает."}}
EOF
